export const sequenceAudioContract=Object.freeze({envelope:sequenceAudioEnvelopeContract,transport:'Sequence voices decode shared PCM even when their audio asset normally streams. Positive/negative rates resample forward/reversed PCM with pitch change; holds/pause/manual/external clocks park without sound.',rate:'root asset rate × game/unscaled clock ratio × each active section one-sided time-map slope × signed clip rate; nonloop child clamps have zero rate. Finite float32 nonzero rate, or0 for a hold.',clips:'Audio clips optionally store reverse:boolean; rate stays a positive0.001..100 magnitude. Source position moves backward from sourceStart with reverse=true and clamps at0. Animation/montage clips reject this audio-only field. Human checkbox and existing document CAS/Undo share validation.',memory:'Reverse PCM is lazy for real reverse voices, shared by weak references to the decoded original, with no additional strong idle cache. Original decoded cache remains32MiB. Active reverse clips can require one additional full PCM copy; no per-frame PCM copy.',lifecycle:'Latest pending seek/rate/pause is applied before asynchronous decode starts playback. Stop/dispose and pause during context resume cancel old starts. Ended sequence PCM voices stay leased until clip/section release, so a later same-clip seek/direction change can restart them. Direction changes restart at the mapped boundary; large drift/explicit seek resynchronizes.',take:'Managed sequence voice transport updates split recorded audio at direction/rate/seek changes and holds. Reverse loop pieces use reverse=true with positive rate magnitude. Unsupported recording rates surface a recording error without stopping game audio. Frame-observed cue times, not PCM sample/genlock alignment.',remaining:['Pitch-preserving time stretch and sample-accurate knot scheduling','Streaming reverse for clips larger than decoded PCM memory','External PCM/timecode clock and hardware genlock']});
